pub fn render(cfg: &HeatmapConfig) -> String {
    let n_rows = cfg.row_labels.len();
    let n_cols = cfg.col_labels.len();
    let n = n_rows * n_cols;
    if n_rows == 0 || n_cols < 2 || cfg.flat_matrix.len() < n {
        return String::new();
    }

    let w = cfg.width;
    let h = cfg.height;
    let label_w = 110.0;
    let top_pad = 30.0;
    let bottom_pad = 22.0;
    let usable_w = (w as f64 - label_w - 12.0).max(10.0);
    let usable_h = (h as f64 - top_pad - bottom_pad).max(10.0);
    let row_h = usable_h / n_rows as f64;

    let color_low = if cfg.color_low == 0 { 0x636EFA } else { cfg.color_low };
    let color_high = if cfg.color_high == 0 { 0xF43F5E } else { cfg.color_high };
    let low_hx = hex6(color_low);
    let high_hx = hex6(color_high);

    let n_bands = 3usize;
    let x_of = |c: usize| -> f64 { label_w + usable_w * c as f64 / (n_cols - 1) as f64 };

    let mut buf = Vec::<u8>::with_capacity(n * 40 + 8192);
    svg_open_rescalable(&mut buf, w, h, 0, 0, w, h);
    push_b(&mut buf, b"<rect class=\"sp-bg\" width=\"100%\" height=\"100%\"/>");
    svg_title(&mut buf, cfg.title, w / 2, 18);

    for r in 0..n_rows {
        let row = &cfg.flat_matrix[r * n_cols..r * n_cols + n_cols];
        let mut max_abs = 1e-6f64;
        for &v in row {
            max_abs = max_abs.max(v.abs());
        }
        let band_size = max_abs / n_bands as f64;
        let top_y = top_pad + row_h * r as f64;
        let base_y = top_y + row_h;

        push_b(&mut buf, b"<clipPath id=\"sphzclip");
        buf.extend_from_slice(r.to_string().as_bytes());
        push_b(&mut buf, b"\"><rect x=\"");
        push_f2(&mut buf, label_w);
        push_b(&mut buf, b"\" y=\"");
        push_f2(&mut buf, top_y);
        push_b(&mut buf, b"\" width=\"");
        push_f2(&mut buf, usable_w);
        push_b(&mut buf, b"\" height=\"");
        push_f2(&mut buf, row_h - 1.0);
        push_b(&mut buf, b"\"/></clipPath>");

        push_b(&mut buf, b"<g clip-path=\"url(#sphzclip");
        buf.extend_from_slice(r.to_string().as_bytes());
        push_b(&mut buf, b")\">");

        for (band, hx, positive) in [(0, &high_hx, true), (1, &high_hx, true), (2, &high_hx, true)]
            .into_iter()
            .chain([(0, &low_hx, false), (1, &low_hx, false), (2, &low_hx, false)])
        {
            let lo = band as f64 * band_size;
            let hi = lo + band_size;
            let opacity = 0.30 + band as f64 * 0.28;
            push_b(&mut buf, b"<path fill=\"#");
            buf.extend_from_slice(hx);
            push_b(&mut buf, b"\" fill-opacity=\"");
            push_f2(&mut buf, opacity);
            push_b(&mut buf, b"\" d=\"M");
            push_f2(&mut buf, x_of(0));
            push_b(&mut buf, b",");
            push_f2(&mut buf, base_y);
            for c in 0..n_cols {
                let v = row[c];
                let mag = if positive { v.max(0.0) } else { (-v).max(0.0) };
                let folded = (mag - lo).clamp(0.0, band_size);
                let px_h = folded / band_size * row_h;
                push_b(&mut buf, b" L");
                push_f2(&mut buf, x_of(c));
                push_b(&mut buf, b",");
                push_f2(&mut buf, base_y - px_h);
            }
            push_b(&mut buf, b" L");
            push_f2(&mut buf, x_of(n_cols - 1));
            push_b(&mut buf, b",");
            push_f2(&mut buf, base_y);
            push_b(&mut buf, b" Z\"/>");
            let _ = hi;
        }
        push_b(&mut buf, b"</g>");

        push_b(&mut buf, b"<text x=\"");
        push_f2(&mut buf, label_w - 8.0);
        push_b(&mut buf, b"\" y=\"");
        push_f2(&mut buf, top_y + row_h * 0.5 + 3.0);
        push_b(&mut buf, b"\" text-anchor=\"end\" font-family=\"-apple-system,Arial,sans-serif\" font-size=\"8.5\" fill=\"#475569\">");
        escape_xml(&mut buf, &cfg.row_labels[r]);
        push_b(&mut buf, b"</text>");

        if r > 0 {
            push_b(&mut buf, b"<line x1=\"");
            push_f2(&mut buf, label_w);
            push_b(&mut buf, b"\" y1=\"");
            push_f2(&mut buf, top_y);
            push_b(&mut buf, b"\" x2=\"");
            push_f2(&mut buf, label_w + usable_w);
            push_b(&mut buf, b"\" y2=\"");
            push_f2(&mut buf, top_y);
            push_b(&mut buf, b"\" stroke=\"#ffffff\" stroke-width=\"1.4\"/>");
        }
    }

    push_b(&mut buf, b"<g fill=\"#94a3b8\" font-family=\"-apple-system,Arial,sans-serif\" font-size=\"8\">");
    for c in 0..n_cols {
        if cfg.col_labels[c].is_empty() {
            continue;
        }
        push_b(&mut buf, b"<text x=\"");
        push_f2(&mut buf, x_of(c));
        push_b(&mut buf, b"\" y=\"");
        push_f2(&mut buf, top_pad + usable_h + 14.0);
        push_b(&mut buf, b"\" text-anchor=\"middle\">");
        escape_xml(&mut buf, &cfg.col_labels[c]);
        push_b(&mut buf, b"</text>");
    }
    push_b(&mut buf, b"</g>");

    push_b(&mut buf, b"</svg>");
    let svg = unsafe { String::from_utf8_unchecked(buf) };
    let slots_json;
    let json: &str = if cfg.hover.is_empty() {
        "[]"
    } else {
        slots_json = crate::html::hover::slots_to_json(cfg.hover);
        &slots_json
    };
    crate::html::hover::build_chart_html(cfg.title, &svg, json)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg<'a>(rows: &'a [String], cols: &'a [String], values: &'a [f64]) -> HeatmapConfig<'a> {
        HeatmapConfig {
            title: "Test",
            row_labels: rows,
            col_labels: cols,
            flat_matrix: values,
            width: 700,
            height: 300,
            ..HeatmapConfig::default()
        }
    }

    fn grid(n_rows: usize, n_cols: usize) -> (Vec<String>, Vec<String>, Vec<f64>) {
        let rows: Vec<String> = (0..n_rows).map(|r| format!("Row{r}")).collect();
        let cols: Vec<String> = (0..n_cols).map(|c| format!("{c}")).collect();
        let values: Vec<f64> = (0..n_rows * n_cols)
            .map(|i| ((i as f64 * 0.3).sin() * 3.0))
            .collect();
        (rows, cols, values)
    }

    #[test]
    fn renders_six_folded_bands_per_row() {
        let (rows, cols, values) = grid(4, 20);
        let html = render(&cfg(&rows, &cols, &values));
        assert!(!html.is_empty());
        assert_eq!(html.matches("<path fill=\"#").count(), 4 * 6);
        assert!(html.contains("class=\"sp-bg\""));
    }

    #[test]
    fn every_row_label_is_present() {
        let (rows, cols, values) = grid(3, 15);
        let html = render(&cfg(&rows, &cols, &values));
        for r in &rows {
            assert!(html.contains(&format!(">{r}<")));
        }
    }

    #[test]
    fn empty_input_returns_empty_string() {
        let rows: Vec<String> = vec![];
        let cols: Vec<String> = vec![];
        let values: Vec<f64> = vec![];
        assert!(render(&cfg(&rows, &cols, &values)).is_empty());
    }

    #[test]
    fn perf_rendering_a_dense_multi_row_horizon_stays_fast() {
        let (rows, cols, values) = grid(40, 200);
        let start = std::time::Instant::now();
        let html = render(&cfg(&rows, &cols, &values));
        let elapsed = start.elapsed();
        assert!(elapsed.as_millis() < 300, "rendering took too long: {elapsed:?}");
        assert!(!html.is_empty());
    }
}
